import { callGroq } from './groq.js';
import { callOllama } from './ollama.js';

export async function getCompletion(prompt, systemPrompt = '', config = {}) {
  const provider = config.provider || 'groq';

  // Primary: Groq
  if (provider === 'groq') {
    try {
      return await callGroq(prompt, systemPrompt, config);
    } catch (err) {
      console.warn(`[Duck Warning] Groq failed: ${err.message}. Falling back to Ollama...`);
      try {
        return await callOllama(prompt, systemPrompt, config);
      } catch (ollamaErr) {
        console.warn(`[Duck Warning] Ollama failed: ${ollamaErr.message}. Falling back to heuristic mode...`);
        return heuristicFallback();
      }
    }
  }

  // Primary: Ollama
  if (provider === 'ollama') {
    try {
      return await callOllama(prompt, systemPrompt, config);
    } catch (err) {
      console.warn(`[Duck Warning] Ollama failed: ${err.message}. Falling back to heuristic mode...`);
      return heuristicFallback();
    }
  }

  throw new Error(`Unknown provider: ${provider}`);
}

function heuristicFallback() {
  return 'chore: update files\n\n(Generated via offline heuristic fallback)';
}
